Input.value:
{
                        path: 'employee>/firstName',
                        type: 'sap.ui.model.odata.type.String',
                        constraints: {
                            maxLength: 40,
                            nullable: false
                        }
                    }

{
                        path: 'employee>/lastName',
                        type: 'sap.ui.model.odata.type.String',
                        constraints: {
                            maxLength: 40,
                            nullable: false
                        }
                    }

{
                        path: 'employee>/countryCode',
                        type: 'sap.ui.model.odata.type.String',
                        constraints: {
                            maxLength: 2,
                            nullable: false
                        }
                    }

DatePicker.value:
{
                        path: 'employee>/dateOfBirth',
                        type: 'sap.ui.model.odata.type.Date',
                        formatOptions: {
                            pattern: 'dd MMMM y',
                            style: 'medium'
                        },
                        constraints: {
                            nullable: false
                        }
                    }
